<section class="purchase-card purchase-activity mb-4"><div class="purchase-section-heading"><span class="material-symbols-outlined" aria-hidden="true">history</span><h2 class="h5 mb-0">Order activity</h2></div><?php foreach ($o['events'] as $e): $details=json_decode($e['details'],true); ?><div class="purchase-event"><strong><?= $esc(ucwords(str_replace('_',' ',$e['action']))) ?></strong><span class="small text-muted"><?= $esc($e['actor_name'].' · '.$e['created_at']) ?> · #<?= (int)$e['operation_id'] ?></span><?php if (!empty($details['notes']) || !empty($details['reason'])): ?><p class="small mb-0"><?= $esc($details['notes'] ?? $details['reason']) ?></p><?php endif; ?></div><?php endforeach; ?></section></div>
