<section class="purchase-card"><h2 class="h5"><?= $selected ? 'Other purchase orders' : 'Latest orders' ?></h2><p class="small text-muted">Showing up to 200 matching orders. Select an order to view its details.</p><div class="table-responsive"><table class="table purchase-table"><thead><tr><th>Order</th><th>Branch</th><th>Supplier</th><th>Status</th><th>Expected</th><th>Ordered cost</th></tr></thead><tbody><?php foreach ($orders as $row): $s=json_decode($row['supplier_snapshot'],true); ?><tr><td><form method="post" action="<?= url('?route=inventory/purchases') ?>"><?php $hidden('purchase_open',['order_id'=>$row['id']]); ?><button type="submit" class="purchase-order-link">PO #<?= (int)$row['id'] ?><span class="material-symbols-outlined" aria-hidden="true">arrow_outward</span></button></form></td><td><?= $esc($row['branch_name']) ?></td><td><?= $esc($s['name'] ?? '') ?></td><td><span class="purchase-status"><?= $esc(str_replace('_',' ',$row['status'])) ?></span></td><td><?= $esc($row['expected_date'] ?: '—') ?></td><td><?= $money($row['ordered_amount']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php if (!$orders): ?><p class="purchase-empty">No purchase orders match these filters.</p><?php endif; ?></section>
<?php if ($can('create_purchase_orders') && $branch): $modalStart('purchaseNew','Create purchase order'); ?>
<form method="post" action="<?= url('?route=inventory/purchases&branch_id='.(int)$branch) ?>" id="purchase-order-form"><?php $hidden('purchase_create',['branch_id'=>$branch]); ?><div class="row g-3"><div class="col-md-8"><label>Supplier<select name="supplier_id" class="form-select" required><option value="">Choose supplier</option><?php foreach ($options as $s): ?><option value="<?= (int)$s['id'] ?>"><?= $esc($s['name']) ?></option><?php endforeach; ?></select></label></div><div class="col-md-4"><label>Expected delivery<input type="date" class="form-control" name="expected_date"></label></div></div><p class="small text-muted mt-3">Creating or approving an order does not add stock. Quantities use the product's base unit. Unit costs include applicable charges.</p><div id="purchase-order-lines"></div><button type="button" class="btn btn-outline-primary" id="purchase-add-line">Add item</button><label class="d-block mt-3">Order notes<textarea class="form-control" name="notes" maxlength="4000"></textarea></label><div class="purchase-actions"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button type="submit" class="btn btn-primary">Save draft order</button></div></form>
<datalist id="purchase-product-suggestions"><?php foreach ($products as $p): ?><option value="<?= $esc($p['name'].' (#'.$p['id'].') · '.$p['unit_type']) ?>" data-product-id="<?= (int)$p['id'] ?>" data-cost="<?= $esc($p['cost_price']) ?>"></option><?php endforeach; ?></datalist>
<p class="small text-muted">Type a product name or number and choose a suggestion. Products are limited to the selected branch.</p>
<template id="purchase-line-template"><fieldset class="purchase-line"><legend>Purchase item</legend><div class="row g-3"><div class="col-12"><label>Product / ingredient<input type="text" class="form-control" data-purchase-product list="purchase-product-suggestions" placeholder="Type a product name or number..." autocomplete="off" required><input type="hidden" data-purchase-field="product_id"></label></div><div class="col-md-5"><label>Quantity<input class="form-control" type="number" data-purchase-field="quantity" min="0.0001" step="0.0001" required></label></div><div class="col-md-5"><label>Agreed unit cost<input class="form-control" type="number" data-purchase-field="unit_cost" min="0" step="0.01" required></label></div><div class="col-md-2 d-flex align-items-end"><button type="button" class="btn btn-outline-danger" data-remove-purchase-line aria-label="Remove purchase item">Remove</button></div></div></fieldset></template>
<?php $modalEnd(); endif; ?>
<?php endif; endif; ?></div>
